const items = $input.all();
const text = (items[0].json.message?.text || '').trim();
const chatId = items[0].json.message?.chat?.id;
const username = items[0].json.message?.from?.username || 'user';

let command = 'help';
if (text === '/report' || text === '/report today') command = 'report';
else if (text === '/report week') command = 'weekly';
else if (text === '/report month') command = 'monthly';

return [{ json: { command, chatId, username } }];

const items = $input.all();
const command = '{{$node["Parse Command"].json.command}}';
const now = new Date();
const today = now.toISOString().split('T')[0];

const sales = items.map(i => ({
  ...i.json,
  amount: parseFloat(i.json.amount || 0),
  date: i.json.date || ''
}));

// Today
const todaySales = sales.filter(s => s.date === today);
const todayTotal = todaySales.reduce((sum, s) => sum + s.amount, 0);
const todayCount = todaySales.length;

// This week (last 7 days)
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const weekSales = sales.filter(s => s.date >= weekAgo);
const weekTotal = weekSales.reduce((sum, s) => sum + s.amount, 0);
const weekCount = weekSales.length;

// This month
const monthStr = today.substring(0, 7);
const monthSales = sales.filter(s => s.date.startsWith(monthStr));
const monthTotal = monthSales.reduce((sum, s) => sum + s.amount, 0);
const monthCount = monthSales.length;

// Top products
const productMap = {};
sales.forEach(s => {
  const p = s.product || 'Unknown';
  if (!productMap[p]) productMap[p] = { count: 0, total: 0 };
  productMap[p].count++;
  productMap[p].total += s.amount;
});
const topProducts = Object.entries(productMap)
  .sort((a, b) => b[1].total - a[1].total)
  .slice(0, 5);

let text = `📊 <b>Sales Dashboard</b>\n`;
text += `━━━━━━━━━━━━━━━━━━\n\n`;

text += `📅 <b>Today (${today})</b>\n`;
text += `  💰 Revenue: Rp ${todayTotal.toLocaleString()}\n`;
text += `  📦 Orders: ${todayCount}\n`;
text += `  📈 Avg: Rp ${todayCount > 0 ? Math.round(todayTotal / todayCount).toLocaleString() : 0}\n\n`;

text += `📆 <b>This Week</b>\n`;
text += `  💰 Revenue: Rp ${weekTotal.toLocaleString()}\n`;
text += `  📦 Orders: ${weekCount}\n\n`;

text += `📅 <b>This Month</b>\n`;
text += `  💰 Revenue: Rp ${monthTotal.toLocaleString()}\n`;
text += `  📦 Orders: ${monthCount}\n\n`;

text += `🏆 <b>Top Products</b>\n`;
topProducts.forEach(([name, data], idx) => {
  text += `  ${idx + 1}. ${name} — Rp ${data.total.toLocaleString()} (${data.count}x)\n`;
});

text += `\n━━━━━━━━━━━━━━━━━━\n`;
text += `Generated: ${now.toISOString()}`;

return [{ json: { text } }];
